    assert!(!is_lock_contention(&classified(
        Class::Retryable,
        ErrorKind::ConnectionReset
    )));
    assert!(!is_lock_contention(&classified(
        Class::Validation,
        ErrorKind::AlreadyExists
    )));
    let io = std::io::Error::from(ErrorKind::AlreadyExists);
    assert!(!is_lock_contention(&io));
}

